import pool from '@/lib/db';
import { revalidatePath } from 'next/cache';

// 🔹 SERVER ACTIONS (Se ejecutan solo en el servidor)
async function addEmpleado(fd: FormData) { 'use server'; await pool.execute('INSERT INTO empleados (nombre_emp) VALUES (?)', [fd.get('nombre_emp')]); revalidatePath('/dashboard'); }
async function deleteEmpleado(fd: FormData) { 'use server'; await pool.execute('DELETE FROM empleados WHERE no_emp = ?', [fd.get('no_emp')]); revalidatePath('/dashboard'); }

async function addGerente(fd: FormData) { 'use server'; await pool.execute('INSERT INTO gerentes (nombre_gerente) VALUES (?)', [fd.get('nombre_gerente')]); revalidatePath('/dashboard'); }
async function deleteGerente(fd: FormData) { 'use server'; await pool.execute('DELETE FROM gerentes WHERE no_gerente = ?', [fd.get('no_gerente')]); revalidatePath('/dashboard'); }

async function addDepto(fd: FormData) { 'use server'; await pool.execute('INSERT INTO departamentos (nombre_depto) VALUES (?)', [fd.get('nombre_depto')]); revalidatePath('/dashboard'); }
async function deleteDepto(fd: FormData) { 'use server'; await pool.execute('DELETE FROM departamentos WHERE num_depto = ?', [fd.get('num_depto')]); revalidatePath('/dashboard'); }

async function addProyecto(fd: FormData) { 'use server'; await pool.execute('INSERT INTO proyectos (nombre_proyecto) VALUES (?)', [fd.get('nombre_proyecto')]); revalidatePath('/dashboard'); }
async function deleteProyecto(fd: FormData) { 'use server'; await pool.execute('DELETE FROM proyectos WHERE num_proyecto = ?', [fd.get('num_proyecto')]); revalidatePath('/dashboard'); }

async function addAsignacion(fd: FormData) { 'use server'; await pool.execute('INSERT INTO asignaciones (no_emp, num_proyecto, fecha_inicio, pagoxhr) VALUES (?, ?, ?, ?)', [fd.get('no_emp'), fd.get('num_proyecto'), fd.get('fecha_inicio'), fd.get('pagoxhr')]); revalidatePath('/dashboard'); }
async function deleteAsignacion(fd: FormData) { 'use server'; await pool.execute('DELETE FROM asignaciones WHERE no_emp = ? AND num_proyecto = ?', [fd.get('no_emp'), fd.get('num_proyecto')]); revalidatePath('/dashboard'); }

// 🔹 CONSULTA DE DATOS (Se ejecuta en el servidor antes de renderizar)
async function getAllData() {
  const [empleados] = await pool.query('SELECT * FROM empleados');
  const [gerentes] = await pool.query('SELECT * FROM gerentes');
  const [departamentos] = await pool.query('SELECT * FROM departamentos');
  const [proyectos] = await pool.query('SELECT * FROM proyectos');
  // Join para mostrar nombres en lugar de solo IDs
  const [asignaciones] = await pool.query(`
    SELECT a.no_emp, a.num_proyecto, a.fecha_inicio, a.pagoxhr, 
           e.nombre_emp, p.nombre_proyecto 
    FROM asignaciones a
    JOIN empleados e ON a.no_emp = e.no_emp
    JOIN proyectos p ON a.num_proyecto = p.num_proyecto
  `);
  return { empleados, gerentes, departamentos, proyectos, asignaciones };
}

// 🔹 COMPONENTE PRINCIPAL
export default async function Dashboard() {
  const { empleados, gerentes, departamentos, proyectos, asignaciones } = await getAllData();

  const TableSection = ({ title, data, formAction, deleteAction, fields }: any) => (
    <section className="mb-8 p-4 border rounded-lg bg-white shadow-sm">
      <h2 className="text-xl font-semibold mb-3">{title}</h2>
      <form action={formAction} className="flex gap-2 mb-4">
        {fields.map((f: string) => (
          <input key={f} name={f} placeholder={f} required className="border p-2 rounded flex-1" />
        ))}
        <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">Agregar</button>
      </form>
      <table className="w-full text-sm border-collapse">
        <thead className="bg-gray-100"><tr>{fields.map(f => <th key={f} className="p-2 border-b text-left">{f}</th>)}<th className="p-2 border-b">Acción</th></tr></thead>
        <tbody>
          {data.map((row: any) => (
            <tr key={row[fields[0]] || row.no_emp || row.num_proyecto} className="border-b hover:bg-gray-50">
              {fields.map(f => <td key={f} className="p-2">{row[f]}</td>)}
              <td className="p-2">
                <form action={deleteAction} className="inline">
                  <input type="hidden" name={fields[0]} value={row[fields[0]]} />
                  <button type="submit" className="text-red-600 hover:text-red-800">🗑️</button>
                </form>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {data.length === 0 && <p className="text-gray-500 text-center py-4">Sin registros</p>}
    </section>
  );

  return (
    <main className="p-6 max-w-6xl mx-auto space-y-6">
      <h1 className="text-3xl font-bold text-gray-800">🏢 Gestión Empresarial</h1>
      
      <TableSection title="👤 Empleados" data={empleados} formAction={addEmpleado} deleteAction={deleteEmpleado} fields={["no_emp","nombre_emp"]} />
      <TableSection title="👔 Gerentes" data={gerentes} formAction={addGerente} deleteAction={deleteGerente} fields={["no_gerente","nombre_gerente"]} />
      <TableSection title="🏛️ Departamentos" data={departamentos} formAction={addDepto} deleteAction={deleteDepto} fields={["num_depto","nombre_depto"]} />
      <TableSection title="📦 Proyectos" data={proyectos} formAction={addProyecto} deleteAction={deleteProyecto} fields={["num_proyecto","nombre_proyecto"]} />
      
      {/* Asignaciones tiene lógica especial por sus 2 campos PK */}
      <section className="mb-8 p-4 border rounded-lg bg-white shadow-sm">
        <h2 className="text-xl font-semibold mb-3">🔗 Asignaciones</h2>
        <form action={addAsignacion} className="flex gap-2 mb-4">
          <input name="no_emp" type="number" placeholder="No. Empleado" required className="border p-2 rounded flex-1" />
          <input name="num_proyecto" type="number" placeholder="No. Proyecto" required className="border p-2 rounded flex-1" />
          <input name="fecha_inicio" type="date" required className="border p-2 rounded flex-1" />
          <input name="pagoxhr" type="number" step="0.01" placeholder="Pago x Hora" required className="border p-2 rounded w-32" />
          <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">Asignar</button>
        </form>
        <table className="w-full text-sm border-collapse">
          <thead className="bg-gray-100"><tr><th className="p-2 border-b">Emp</th><th className="p-2 border-b">Proy</th><th className="p-2 border-b">Empleado</th><th className="p-2 border-b">Proyecto</th><th className="p-2 border-b">Inicio</th><th className="p-2 border-b">Pago/hr</th><th className="p-2 border-b"></th></tr></thead>
          <tbody>
            {asignaciones.map((a: any) => (
              <tr key={`${a.no_emp}-${a.num_proyecto}`} className="border-b hover:bg-gray-50">
                <td className="p-2">{a.no_emp}</td><td className="p-2">{a.num_proyecto}</td>
                <td className="p-2">{a.nombre_emp}</td><td className="p-2">{a.nombre_proyecto}</td>
                <td className="p-2">{new Date(a.fecha_inicio).toLocaleDateString()}</td>
                <td className="p-2">${Number(a.pagoxhr).toFixed(2)}</td>
                <td className="p-2">
                  <form action={deleteAsignacion}>
                    <input type="hidden" name="no_emp" value={a.no_emp} />
                    <input type="hidden" name="num_proyecto" value={a.num_proyecto} />
                    <button type="submit" className="text-red-600 hover:text-red-800">🗑️</button>
                  </form>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {asignaciones.length === 0 && <p className="text-gray-500 text-center py-4">Sin asignaciones</p>}
      </section>
    </main>
  );
}